int save_processor_state(struct xsave_struct *fx, u64 mask) {
    int ret = 0;

    asm volatile(
        "alternative_if_not .Lno_xsaves\n"
        "  xsaves %0, %1\n"
        "alternative_else\n"
        "  alternative_if .Lno_xsaveopt\n"
        "    xsave %0, %1\n"
        "  alternative_endif\n"
        "  .Lno_xsaves:\n"
        "alternative_endif"
        : : "m"(*fx), "r"(mask)
        : "memory"
    );

    return ret;
}

int save_xsave_state(struct xsave_struct *fx, u64 mask) {
    int err = 0;

    asm volatile(
        ".alternative_if_not 0\n"
        "xsave %0\n"
        ".alternative_else 0\n"
        ".alternative_if 1\n"
        "xsaveopt %0\n"
        ".alternative_else 1\n"
        "xsaves %0\n"
        ".alternative_endif\n"
        ".alternative_endif\n"
        : : "m"(*fx), "i"(mask) : "memory");

    return err;
}

int save_extended_processor_state(struct xsave_struct *fx, u64 mask)
{
    int error = 0;

    asm volatile(
        "test %[mask], %[bitmask]\n\t"
        "jnz 1f\n\t"
        "xsave %[fx]\n\t"
        "jmp 2f\n\t"
        "1:\n\t"
        "xsaves %[fx]\n\t"
        "2:"
        : [fx] "=m" (*fx)
        : [mask] "r" (mask), [bitmask] "n" (XSAVE_SAVES_MASK)
        : "memory");

    return error;
}
